const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
let selectedCat="Todos", query="", favorites=new Set(JSON.parse(localStorage.getItem("bancaFavs")||"[]"));

function saveFavs(){localStorage.setItem("bancaFavs",JSON.stringify([...favorites])); updateFavCount();}
function updateFavCount(){ $("#favCount").textContent=favorites.size; }
function cardHTML(c){const color=categories[c.cat]?.color||"#1464a5";return `<article class="concept-card" data-id="${c.id}" style="--accent:${color}"><div class="concept-head"><div class="concept-main"><div class="concept-titleline"><h3>${categories[c.cat]?.icon||"📘"} ${c.title}</h3><span class="badge">${c.cat}</span></div><p class="short">${c.short}</p></div><button class="fav ${favorites.has(c.id)?"on":""}" aria-label="Favorito">★</button><button class="expand" aria-label="Abrir">⌄</button></div><div class="concept-body"><div class="detail-block"><b>Ejemplo rápido</b><p>${c.example}</p></div><div class="detail-block"><b>No lo confundas con…</b><p>${c.dont}</p></div><div class="detail-block"><b>Cliente podría decir</b><p>${c.client}</p></div><div class="detail-block"><b>Como asesor piensa</b><p>${c.advisor}</p></div><div class="source-note">Fuente/nota: ${c.source}</div></div></article>`}

function renderChips(){const names=["Todos",...Object.keys(categories)];$("#categoryChips").innerHTML=names.map(n=>`<button class="chip ${n===selectedCat?"active":""}" data-cat="${n}">${n==="Todos"?"✨":categories[n].icon} ${n}</button>`).join("");$$('.chip').forEach(b=>b.onclick=()=>{selectedCat=b.dataset.cat;renderChips();renderConcepts();});}
function filtered(){const q=query.trim().toLowerCase();return concepts.filter(c=>(selectedCat==="Todos"||c.cat===selectedCat)&&(!q||[c.title,c.short,c.example,c.dont,c.client,c.advisor,c.cat].join(" ").toLowerCase().includes(q)));}
function bindCards(root){root.querySelectorAll('.concept-card').forEach(card=>{card.querySelector('.expand').onclick=e=>{e.stopPropagation();card.classList.toggle('open')};card.querySelector('.concept-head').onclick=e=>{if(e.target.closest('.fav')||e.target.closest('.expand'))return;card.classList.toggle('open')};card.querySelector('.fav').onclick=e=>{e.stopPropagation();const id=card.dataset.id;favorites.has(id)?favorites.delete(id):favorites.add(id);saveFavs();card.querySelector('.fav').classList.toggle('on',favorites.has(id));renderFavorites();};});}
function renderConcepts(){const arr=filtered();$("#resultSummary").textContent=`${arr.length} concepto${arr.length===1?"":"s"}${selectedCat!=="Todos"?` en ${selectedCat}`:""}`;const grid=$("#conceptGrid");grid.innerHTML=arr.length?arr.map(cardHTML).join(""):`<div class="empty">No encontré conceptos con esa búsqueda.</div>`;bindCards(grid);}
function renderFavorites(){const arr=concepts.filter(c=>favorites.has(c.id));const grid=$("#favGrid");grid.innerHTML=arr.length?arr.map(cardHTML).join(""):`<div class="empty">Todavía no guardas conceptos. Marca ⭐ en cualquiera.</div>`;bindCards(grid);}
function renderCases(){ $("#caseGrid").innerHTML=cases.map((c,i)=>`<article class="case-card"><span class="case-tag">${c.tag}</span><h3>Caso ${i+1}</h3><div class="client-quote">${c.q}</div><details><summary>¿Cómo lo pensaría?</summary><ol>${c.steps.map(s=>`<li>${s}</li>`).join("")}</ol><p class="source-note">Los pasos son una guía mental de estudio. La operación exacta se valida en CUC/MAU vigente.</p></details></article>`).join("");}

function switchTab(id){$$('.tabpage').forEach(p=>p.classList.toggle('active',p.id===id));$$('.navtab').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));window.scrollTo({top:document.querySelector('.topnav').offsetTop,behavior:'smooth'});if(id==='favoritos')renderFavorites();}
$$('.navtab').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$$('[data-go]').forEach(b=>b.onclick=()=>switchTab(b.dataset.go));
$("#searchInput").addEventListener('input',e=>{query=e.target.value;renderConcepts();});$("#clearSearch").onclick=()=>{$("#searchInput").value="";query="";selectedCat="Todos";renderChips();renderConcepts();};

$("#randomBtn").onclick=()=>{const c=concepts[Math.floor(Math.random()*concepts.length)];$("#randomContent").innerHTML=`<div class="random-card"><div class="random-cat">${categories[c.cat].icon} ${c.cat}</div><h3>${c.title}</h3><p><strong>Qué es:</strong> ${c.short}</p><p><strong>Ejemplo:</strong> ${c.example}</p><p><strong>No confundas:</strong> ${c.dont}</p></div>`;$("#randomDialog").showModal();};$("#closeRandom").onclick=()=>$("#randomDialog").close();

let qset=[],qi=0,score=0,answered=false;
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function startQuiz(){qset=shuffle(quiz).slice(0,10);qi=0;score=0;answered=false;$("#quizRestart").classList.add('hidden');showQ();}
function showQ(){answered=false;const q=qset[qi];$("#quizProgress").textContent=`${qi+1} / ${qset.length}`;$("#quizScore").textContent=`${score} correctas`;$("#quizBar").style.width=`${((qi+1)/qset.length)*100}%`;$("#quizQuestion").textContent=q.q;$("#quizOptions").innerHTML=q.o.map((o,i)=>`<button class="quiz-option" data-i="${i}">${o}</button>`).join("");$("#quizExplain").className='quiz-explain';$("#quizExplain").textContent='';$("#quizNext").classList.add('hidden');$$('.quiz-option').forEach(b=>b.onclick=()=>answerQ(Number(b.dataset.i)));}
function answerQ(i){if(answered)return;answered=true;const q=qset[qi];if(i===q.a)score++;$$('.quiz-option').forEach((b,idx)=>{b.disabled=true;if(idx===q.a)b.classList.add('correct');else if(idx===i)b.classList.add('wrong');});$("#quizScore").textContent=`${score} correctas`;$("#quizExplain").textContent=q.e;$("#quizExplain").classList.add('show');$("#quizNext").classList.remove('hidden');}
$("#quizNext").onclick=()=>{if(qi<qset.length-1){qi++;showQ();}else{$("#quizQuestion").textContent=`Terminaste: ${score} de ${qset.length} correctas`;$("#quizOptions").innerHTML='';$("#quizExplain").className='quiz-explain show';$("#quizExplain").textContent=score>=8?'Vas muy bien. Ahora intenta explicar los conceptos sin leerlos.':'Repasa tus errores y vuelve a intentarlo; la meta es entender la lógica, no memorizar letras.';$("#quizNext").classList.add('hidden');$("#quizRestart").classList.remove('hidden');}};$("#quizRestart").onclick=startQuiz;

renderChips();renderConcepts();renderCases();renderFavorites();updateFavCount();startQuiz();
